{
  "packet_id": "H6-T01-3",
  "claim_id": "C008",
  "status": "SUPPORTED",
  "claim": {
    "component_id": "C008.component",
    "value": "Scheduled start, physical return, cleaning completion, readiness for collection, collection and actual work start must be distinguished as different events or milestones.",
    "scope": "Event definitions in the booking timelines; this distinction does not assert that their recorded times must always differ.",
    "provenance": {
      "refs": [
        {
          "source_id": "P004",
          "role": "SUPPORT"
        },
        {
          "source_id": "P031",
          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "P004 supplies the full distinction, and P031 reinforces that readiness, collection and work start are different events. Neither requires different timestamps."
    }
  },
  "signal_basis": {
    "component_id": "C008.signal_basis",
    "value": "Assemble booking-level timelines and compare independent evidence concerning the same equipment, booking and handoff, corroborating specific timing or status features such as return relative to scheduled start or cleaning completion.",
    "scope": "Event-specific comparison within booking timelines; agreement about one milestone does not establish another milestone.",
    "provenance": {
      "refs": [
        {
          "source_id": "P006",
          "role": "SUPPORT"
        },
        {
          "source_id": "P016",
          "role": "SUPPORT"
        },
        {
          "source_id": "P017",
          "role": "SUPPORT"
        },
        {
          "source_id": "P022",
          "role": "SUPPORT"
        },
        {
          "source_id": "P031",
          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "These spans supply timeline construction, handoff-specific independent comparison, concrete corroboration examples and the restriction to the particular feature established."
    }
  },
  "stated_empirical_relation": {
    "component_id": "C008.stated_empirical_relation",
    "value": "NOT_APPLICABLE",
    "scope": "NOT_APPLICABLE",
    "provenance": {
      "refs": [],
      "support_status": "SUFFICIENT",
      "rationale": "The claim concerns distinctions between event definitions, not an unresolved empirical relation."
    }
  },
  "rationale": "The operation requires identifying which event each observation concerns. The named milestones describe distinct scheduling, physical and operational conditions, so evidence about one cannot automatically establish another. This licenses distinguishing them even when some timestamps coincide.",
  "uncertainty": "No material uncertainty within the stated definitional scope; the claim does not establish any event's timing or the cause of lateness.",
  "anomalies": []
}
